  const select=(key,values)=>`<select data-need="${key}"><option value="">Not specified</option>${values.map(v=>`<option ${n[key]===v?'selected':''}>${e(v)}</option>`).join('')}</select>`;
  const d=modal('Buying requirements · '+c.name,`<div class="hub-grid"><label class="hub-field">Payment${select('purchaseMethod',['Cash','Financing','Undecided'])}</label><label class="hub-field">Body style${select('bodyStyle',['SUV','Sedan','Hatchback','Truck','Van','Wagon','Coupe','Convertible','Other'])}</label>
  <label class="hub-field">Maximum vehicle price ($)<input type="number" min="0" step="1" data-need="maxPrice" value="${e(n.maxPrice??'')}"></label><label class="hub-field">Maximum odometer (km)<input type="number" min="0" step="1" data-need="maxOdometerKm" value="${e(n.maxOdometerKm??'')}"></label>
  <label class="hub-field full">CARFAX preference${select('carfaxPreference',['No reported accidents preferred','Report to be reviewed together','No preference stated'])}</label>
  <label class="hub-field full">Reason for buying<textarea data-need="reason" maxlength="1000">${e(n.reason||'')}</textarea></label><label class="hub-field full">Purchase timeframe<input data-need="timeframe" maxlength="1000" value="${e(n.timeframe||'')}"></label><label class="hub-field full">Features / other needs<textarea data-need="features" maxlength="1000">${e(n.features||'')}</textarea></label></div>
  <p class="hub-caption">These are the customer’s stated preferences, not financing approval or a claim about a vehicle’s history. Future inventory-match reminders can use these fields; no messages are sent automatically.</p><div class="hub-end"><button class="hub-btn primary" id="hub-save-needs">Save requirements</button></div>`);
  action($('#hub-save-needs',d),async()=>{const value={};$$('[data-need]',d).forEach(input=>value[input.dataset.need]=input.value);const purchaseNeeds=H.normalizeNeeds(value);await S.save('contact',{...c,purchaseNeeds});d.close();await onSaved?.();toast('Buying requirements saved with this customer.');});
