function printContact(c){
  if(document.body.dataset.lotkeysLocked==='true')return;
  const frame=document.createElement('iframe');frame.title='Customer summary print preview';frame.style.cssText='position:fixed;left:-12000px;top:0;width:800px;height:1000px;border:0';
  const fields=(c.fields||[]).map(f=>`<tr><th>${e(f.label)}${f.primary?' · Primary':''}</th><td>${e(f.value)}</td></tr>`).join('');
  frame.onload=()=>{const w=frame.contentWindow;w.addEventListener('afterprint',()=>frame.remove(),{once:true});w.focus();w.print();setTimeout(()=>frame.remove(),60000);};
  frame.srcdoc=`<!doctype html><html><head><meta charset="utf-8"><title>${e(c.name)} · LotKeys customer</title><style>body{font:12pt Arial,sans-serif;margin:28px;line-height:1.4;color:#111}h1{margin-bottom:4px}h2{font-size:15pt;border-bottom:1px solid #ccc;padding-bottom:5px}.hub-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.hub-field span{font-weight:bold;display:block}table{border-collapse:collapse;width:100%}th,td{text-align:left;vertical-align:top;padding:6px;border-bottom:1px solid #ddd}th{width:30%}p{white-space:pre-wrap}.note{break-inside:avoid}small{color:#555}@page{margin:16mm}</style></head><body><h1>${e(c.name)}</h1><small>${e(H.stateLabel(c))} · ${e(catFor(c)?.name||'Uncategorized')} · Printed ${e(new Date().toLocaleString())}</small><h2>Contact details</h2><table>${fields}</table><h2>Buying requirements</h2>${needsSummary(c)}<h2>Saved notes</h2>${(c.notes||[]).map(n=>`<div class="note"><strong>${e(n.label||'Note')}</strong><p>${e(n.text)}</p></div>`).join('')||'<p>No notes saved.</p>'}<h2>Saved attachments</h2>${(c.attachments||[]).map(f=>`<p>${e(f.name)}</p>`).join('')||'<p>No saved attachments.</p>'}<small>This summary is a deliberate copy. Phone message history is not included.</small></body></html>`;
  document.body.append(frame);
}
async function assignCategory(rowId,categoryId){
  if(document.body.dataset.lotkeysLocked==='true')throw Error('Unlock LotKeys first.');
  const target=categories.find(c=>c.id===categoryId),id=target?.id||'';
  const t=rowId.startsWith('contact:')?null:D.get(rowId),c=rowId.startsWith('contact:')?await S.get('contact',rowId.slice(8)):t?resolveThread(t):null;
  if(!c){if(!t)return;await editContact('',{name:t.title,phone:H.validPhone(t.address)?t.address:'',threadId:t.id,categoryId:id});return;}
  const fresh=await S.get('contact',c.id);if(!fresh||fresh._owner!==c._owner)throw Error('Account or customer changed.');
  await S.save('contact',{...fresh,categoryId:id});await refresh();toast(c.name+' → '+(target?.name||'Uncategorized'));
}
function chooseCategory(rowId){
  const d=modal('Move conversation',`<div class="hub-grid"><button class="hub-btn" data-move-cat="">Uncategorized</button>${categories.map(c=>`<button class="hub-btn" data-move-cat="${e(c.id)}" style="border-color:${e(c.color)}">${e(c.name)}</button>`).join('')}</div><p class="hub-caption">Moving an unsaved person first opens a contact form. It does not silently save personal conversations.</p>`);
  $$('[data-move-cat]',d).forEach(b=>action(b,async()=>{const category=b.dataset.moveCat;d.close();await assignCategory(rowId,category);}));
}
function wireCategoryDrag(row){
  if(scope!=='device')return;const id=row.dataset.deviceId,grip=$('.hub-drag-handle',row);let hold,touch=null,ghost=null,lifted=false;
  const cleanup=()=>{clearTimeout(hold);ghost?.remove();ghost=null;draggedRow='';$$('.hub-drop-target').forEach(n=>n.classList.remove('hub-drop-target'));setTimeout(()=>{suppressRowClick=false;},80);};
  row.ondragstart=ev=>{draggedRow=id;suppressRowClick=true;ev.dataTransfer.effectAllowed='move';ev.dataTransfer.setData('text/plain',id);};row.ondragend=()=>{cleanup();paintRows();};
  if(!grip)return;
  grip.onclick=ev=>{ev.preventDefault();ev.stopPropagation();if(!lifted&&!suppressRowClick)chooseCategory(id);};
  grip.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();ev.stopPropagation();chooseCategory(id);}};
  grip.onpointerdown=ev=>{
    if(ev.pointerType==='mouse')return;ev.stopPropagation();touch={x:ev.clientX,y:ev.clientY,id:ev.pointerId};lifted=false;
    grip.setPointerCapture(ev.pointerId);
    hold=setTimeout(()=>{if(!touch)return;lifted=true;draggedRow=id;suppressRowClick=true;ghost=document.createElement('div');ghost.className='hub-drag-ghost';ghost.textContent=row.querySelector('strong')?.textContent||'Conversation';ghost.style.left=touch.x+'px';ghost.style.top=touch.y+'px';document.body.append(ghost);navigator.vibrate?.(20);},300);
  };
  grip.onpointermove=ev=>{
    if(!touch)return;touch.x=ev.clientX;touch.y=ev.clientY;if(!lifted)return;ev.preventDefault();if(ghost){ghost.style.left=ev.clientX+'px';ghost.style.top=ev.clientY+'px';}
    $$('.hub-drop-target').forEach(n=>n.classList.remove('hub-drop-target'));document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-category]')?.classList.add('hub-drop-target');
  };
  grip.onpointerup=ev=>{
    if(!touch)return;const moved=lifted,target=moved?document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-category]'):null;touch=null;cleanup();
    if(moved){suppressRowClick=true;if(target)assignCategory(id,target.dataset.category).catch(report);ev.preventDefault();}setTimeout(()=>{lifted=false;suppressRowClick=false;},120);
  };
  grip.onpointercancel=()=>{touch=null;lifted=false;cleanup();};
}

