function init(){let wasLocked=document.body.dataset.lotkeysLocked==='true';const guard=new MutationObserver(()=>{const locked=document.body.dataset.lotkeysLocked==='true';if(locked){$$('dialog.hub-dialog').forEach(d=>d.close());$('#hub-toast')?.setAttribute('hidden','');}else if(wasLocked){D.wake?.();if(home()){paintStatus();paintRows();}else if(deviceId)paintDevice();}wasLocked=locked;});guard.observe(document.body,{attributes:true,attributeFilter:['data-lotkeys-locked']});const nav=$('#chat-nav-btn');if(nav){const label=$('small',nav);if(label)label.textContent='Hub';nav.title='Hub · hold for the most recent conversation';nav.setAttribute('aria-label','Hub. Hold to preview the most recent conversation.');}window.addEventListener('pagehide',()=>{$$('dialog.hub-dialog').forEach(d=>d.close());clearThumbs();});setInterval(()=>{if(home()){$('.hub-clock',panel()).innerHTML=`<strong>${e(time(Date.now()))}</strong>${e(new Date().toLocaleDateString())}`;}if(shown())S.identity().catch(()=>{});},10000);}
